package main

import (
	"fmt"
	"math"
	"strings"

	"github.com/NimbleMarkets/ntcharts/linechart/streamlinechart"
	"github.com/NimbleMarkets/ntcharts/sparkline"
	"github.com/charmbracelet/lipgloss"
)

var bg = lipgloss.Color("#1e1e2e")

func samples(n int) []float64 {
	out := make([]float64, n)
	for i := 0; i < n; i++ {
		out[i] = 50 + 45*math.Sin(float64(i)/4) + 5*math.Sin(float64(i)/1.3)
	}
	return out
}

func show(label, s string) {
	fmt.Printf("=== %s ===\n", label)
	for _, line := range strings.Split(s, "\n") {
		fmt.Printf("|%s|  (len=%d)\n", line, lipgloss.Width(line))
	}
	fmt.Println()
}

func main() {
	style := lipgloss.NewStyle().Foreground(lipgloss.Color("#a6e3a1")).Background(bg)

	// 1. one-line sparkline (blocks)
	sl := sparkline.New(40, 1, sparkline.WithStyle(style), sparkline.WithMaxValue(100), sparkline.WithNoAutoMaxValue())
	sl.PushAll(samples(40))
	sl.Draw()
	show("sparkline 40x1 blocks", sl.View())

	// 2. multi-line sparkline
	sl2 := sparkline.New(40, 4, sparkline.WithStyle(style), sparkline.WithMaxValue(100), sparkline.WithNoAutoMaxValue())
	sl2.PushAll(samples(40))
	sl2.Draw()
	show("sparkline 40x4 blocks", sl2.View())

	// 3. braille sparkline
	sl3 := sparkline.New(40, 4, sparkline.WithStyle(style), sparkline.WithMaxValue(100), sparkline.WithNoAutoMaxValue())
	sl3.PushAll(samples(80))
	sl3.DrawBraille()
	show("sparkline 40x4 braille", sl3.View())

	// 4. DrawColumnsOnly — background trap check
	sl4 := sparkline.New(40, 3, sparkline.WithStyle(style), sparkline.WithMaxValue(100), sparkline.WithNoAutoMaxValue())
	sl4.PushAll(samples(40))
	sl4.DrawColumnsOnly()
	show("sparkline 40x3 DrawColumnsOnly", sl4.View())

	// 5. streamlinechart, two datasets
	sc := streamlinechart.New(48, 8)
	sc.SetStyles(runesLight(), style)
	sc.SetViewYRange(0, 100)
	sc.SetDataSetStyles("mem", runesLight(), lipgloss.NewStyle().Foreground(lipgloss.Color("#89b4fa")).Background(bg))
	for _, v := range samples(48) {
		sc.Push(v)
		sc.PushDataSet("mem", 100-v)
	}
	sc.DrawAll()
	show("streamlinechart 48x8 two series", sc.View())
}

